cd /tmp/claude-0/-home-user-claude-middleware/0717732f-216e-5d96-be1b-25ee0c15e48c/scratchpad/tb2/multi-source-data-merger/pstack-1/work; cat > merge.py <<'EOF'
import json
import pandas as pd

FIELD_MAP = {
    "user_id": "user_id", "id": "user_id", "userId": "user_id",
    "email": "email", "email_address": "email",
    "full_name": "name", "name": "name", "userName": "name",
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "status": "status",
}
ACTIVE_COLS = ("is_active", "active")
FIELDS = ["name", "email", "created_date", "status"]
SOURCES = ["source_a", "source_b", "source_c"]


def to_bool(v):
    if isinstance(v, str):
        return v.strip().lower() in ("true", "1", "yes", "y", "t")
    return bool(v)


def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)) or v == "":
        return None
    return pd.to_datetime(v).strftime("%Y-%m-%d")


def normalize(df):
    out = {}
    for col in df.columns:
        if col in FIELD_MAP:
            out[FIELD_MAP[col]] = df[col]
    if "status" not in out:
        for col in ACTIVE_COLS:
            if col in df.columns:
                out["status"] = df[col].map(lambda v: "active" if to_bool(v) else "inactive")
                break
    nd = pd.DataFrame(out)
    nd["user_id"] = nd["user_id"].astype(int)
    if "created_date" in nd:
        nd["created_date"] = nd["created_date"].map(norm_date)
    records = {}
    for row in nd.to_dict("records"):
        records[int(row["user_id"])] = {
            f: (None if pd.isna(row.get(f)) else str(row.get(f))) if row.get(f) is not None else None
            for f in FIELDS
        }
    return records


with open("/data/source_a/users.json") as fh:
    a = pd.DataFrame(json.load(fh))
b = pd.read_csv("/data/source_b/users.csv", dtype=str)
c = pd.read_parquet("/data/source_c/users.parquet")
data = dict(zip(SOURCES, [normalize(a), normalize(b), normalize(c)]))

all_ids = sorted(set().union(*[d.keys() for d in data.values()]))
rows, conflicts = [], []
for uid in all_ids:
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {s: data[s][uid][f] for s in SOURCES if uid in data[s] and data[s][uid][f] is not None}
        selected = next(iter(vals.values()), None)
        row[f] = selected
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": selected})
    rows.append(row)

df = pd.DataFrame(rows, columns=["user_id"] + FIELDS)
df["user_id"] = df["user_id"].astype("int64")
for f in FIELDS:
    df[f] = df[f].astype(object)
df.to_parquet("/app/merged_users.parquet", index=False)
with open("/app/conflicts.json", "w") as fh:
    json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, fh, indent=2)
print(df.to_string()); print(df.dtypes)
print(json.dumps(conflicts, indent=2))
EOF
